from lib import *
S = SS('g60')
steps = [
    step("用 -race 逐个检验:写 x 之后用某种同步,另一边读 x,到底有没有 happens-before。无竞争的:缓冲 channel 的 send→receive、close→receive、无缓冲 channel 对方先 receive 再 send 完成、容量 1 的 channel 第 2 次 send 完成之后读、mutex 的 Unlock→Lock、atomic.Bool 的 Store/Load 当发布标志、sync.Once、WaitGroup 的 Done→Wait、go 语句之前的写。报告 DATA RACE 的:容量 1 的 channel 只 send 一次就读 x(睡 20 ms 也一样)、只靠 time.Sleep(50ms)、只靠 runtime.Gosched() 与 Sleep。", t=tl(S(1)), done=lidx(S(1), '[chan-send]', '[chan-close]', '[unbuf-recv]', '[buf1-recv-second]', '[mutex]', '[atomic-flag]', '[once]', '[waitgroup]', '[go-stmt]'), mark=lidx(S(1), '[buf1-recv-single]', '[sleep-only]', '[gosched-only]'), b=bars([['建立了 happens-before', 9, '9 种'], ['没有建立', 3, '3 种']], 9, done=[0], mark=[1]), kv=KV([['有效的同步', 'channel、close、mutex、atomic、Once、WaitGroup、go 语句'], ['没用的', 'Sleep、Gosched、容量 1 channel 只 send 一次'], ['容量 C 的规则', '第 k 次 receive 在第 k+C 次 send 完成之前']], ['没用的'])),
    step("弱内存序是真的(arm64)。SB 测试(线程 A:x=1; r1=y;线程 B:y=1; r2=x,各 200 万轮):用普通变量,r1=0 且 r2=0 出现 27591 次(顺序一致的执行里这不可能);改用 sync/atomic,出现 0 次。MP 测试(线程 A:data=1; flag=1;线程 B:f=flag; d=data):普通变量下 f=1 且 d=0 出现 0 次,flag 用 atomic 也是 0 次——这次没有观察到重排,但不代表它不会发生。", t=tl(S(2)), done=lidx(S(2), 'sync/atomic:r1=0', 'flag 用 atomic', '普通变量:f=1'), mark=lidx(S(2), '普通变量:r1=0 且 r2=0 出现 27591 次'), b=bars([['SB 普通变量:出现 (次)', 27591, '27591'], ['SB sync/atomic', 0, '0'], ['MP 普通变量', 0, '0'], ['MP flag 用 atomic', 0, '0']], 27591, mark=[0], done=[1, 2, 3]), kv=KV([['SB 普通变量', '200 万轮里 27591 次(约 1.4%)'], ['SB 用 atomic', '0 次'], ['MP', '两种写法都是 0 次,没观察到']], ['SB 普通变量'])),
    step("Go 内存模型文档(本机 $GOROOT/doc/go_mem.html)原文:A send on a channel is synchronized before the completion of the corresponding receive;The closing of a channel is synchronized before a receive that returns a zero value;A receive from an unbuffered channel is synchronized before the completion of the corresponding send;The kth receive from a channel with capacity C is synchronized before the completion of the k+Cth send;Unlock 的第 n 次调用 synchronized before Lock 的第 m 次返回;go 语句 synchronized before 新 goroutine 开始执行;原子操作的效果被另一个原子操作观察到则 synchronized before;data race 的定义;以及最后那句 “you are being too clever. Don't be clever.”", t=tl(S(3)), done=lidx(S(3), 'A send on a channel', 'The closing of a channel', 'A receive from an unbuffered', 'The kth receive', 'call n of l.Unlock()', 'The go statement', 'atomic operation A'), mark=lidx(S(3), 'A data race is defined', 'Don\'t be clever'), kv=KV([['channel', 'send→receive、close→receive、无缓冲 receive→send 完成、kth receive→k+C 次 send'], ['锁与 go', 'Unlock→Lock、go 语句→新 goroutine'], ['原子操作', '被观察到的写在读之前同步'], ['态度', 'Don\'t be clever']], ['态度'])),
]
A = mkartg('g60', 60, 'Go,内存模型,happens-before,原子操作,真实验证,动画演示',
    '在 Go 1.27.1(arm64)里验证内存模型:用 -race 逐个检验 12 种同步,channel、close、mutex、atomic、Once、WaitGroup、go 语句都建立了 happens-before,Sleep、Gosched 和容量 1 channel 只 send 一次不行;SB 测试里普通变量 200 万轮出现 27591 次 r1=r2=0,sync/atomic 为 0 次;并摘录文档中各条同步规则。',
    '“写了 x,另一个 goroutine 一定能读到吗?”靠的是 happens-before。这篇用竞态检测器逐个检验 channel、锁、原子操作等是否真的建立了它,在 arm64 上跑 litmus 测试证明弱内存序不是纸面理论,并对着本机的内存模型文档逐条读规则。',
    [('9 + 3', '12 种同步写法里,建立了 happens-before 的 9 种,没有建立的 3 种(Sleep、Gosched、容量 1 channel 只 send 一次)'), ('27591 次', 'SB 测试 200 万轮里普通变量出现 r1=r2=0 的次数,sync/atomic 为 0'), ('k+C', '容量 C 的 channel:第 k 次 receive 在第 k+C 次 send 完成之前同步')],
    [('哪些同步有用', '<p>channel 的 send→receive、close→receive、无缓冲 channel 的 receive→send 完成、mutex 的 Unlock→Lock、<code>atomic</code> 的 Store/Load 作发布标志、<code>sync.Once</code>、<code>WaitGroup</code>、<code>go</code> 语句,用 -race 检验都没有竞争。睡眠和 <code>Gosched</code> 不是同步,会被报告。</p>'),
     ('容量为 C 的 channel 要看规则', '<p>容量 1 的 channel 只 send 一次就读 x,即使 goroutine 稍后才 receive 也是竞争,因为 send 到缓冲区不等 receive。第 2 次 send 才需要第 1 次 receive 先发生,这时读 x 就安全。这正是文档里 “第 k 次 receive 在第 k+C 次 send 完成之前”的含义。</p>'),
     ('弱内存序真的会出现,文档的结论是别耍聪明', '<p>SB 测试里,普通变量在 200 万轮中有 27591 次出现“两边都没看到对方的写”;换成 <code>sync/atomic</code> 是 0 次。我另外试了 MP 测试,普通变量和 atomic 都是 0 次,这次没观察到重排——没观察到不等于不会发生,文档对有数据竞争的程序没有给任何保证。本机文档把规则写成一条条 “synchronized before”,最后劝你别耍聪明:先找到一条规则把读写连起来,找不到就加同步。</p>')],
    steps,
    [ENV_G + '。第一节每种同步是一个小程序,用 go build -race 编译后运行一次看是否报告 DATA RACE;litmus 测试在 arm64(GOMAXPROCS=4)上各 200 万轮,每轮用原子计数器做屏障,测试变量本身是普通 int32 或 sync/atomic;文档引用来自本机 $GOROOT/doc/go_mem.html,逐句核对过原文存在',
     '没有验证:x86 上的结果、MP 测试在更多轮次/更多线程下是否出现重排、编译器重排(只看了硬件+编译器的联合表现)、Go 1.19 之后内存模型对原子操作顺序一致的完整表述、unsafe 与 cgo 场景'],
    'Go 内存模型')
